use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Indicates the confidence in the correctness of a suggestion."] # [doc = ""] # [doc = " All suggestions are marked with an `Applicability`. Tools use the applicability of a suggestion"] # [doc = " to determine whether it should be automatically applied or if the user should be consulted"] # [doc = " before applying the suggestion."] # [derive (Copy , Clone , Debug , Hash , Encodable , Decodable , Serialize , Deserialize , PartialEq , Eq , PartialOrd , Ord ,)] pub enum Applicability { # [doc = " The suggestion is definitely what the user intended, or maintains the exact meaning of the code."] # [doc = " This suggestion should be automatically applied."] # [doc = ""] # [doc = " In case of multiple `MachineApplicable` suggestions (whether as part of"] # [doc = " the same `multipart_suggestion` or not), all of them should be"] # [doc = " automatically applied."] MachineApplicable , # [doc = " The suggestion may be what the user intended, but it is uncertain. The suggestion should"] # [doc = " result in valid Rust code if it is applied."] MaybeIncorrect , # [doc = " The suggestion contains placeholders like `(...)` or `{ /* fields */ }`. The suggestion"] # [doc = " cannot be applied automatically because it will not result in valid Rust code. The user"] # [doc = " will need to fill in the placeholders."] HasPlaceholders , # [doc = " The applicability of the suggestion is unknown."] Unspecified , }